import{_ as a,a as t,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"行为型设计模式","description":"围绕替换计算规则、控制执行流程、组件通信、恢复历史与遍历结构选择模式；区分状态切换、通知机制和对象上的新操作。","frontmatter":{"title":"行为型设计模式","description":"围绕替换计算规则、控制执行流程、组件通信、恢复历史与遍历结构选择模式；区分状态切换、通知机制和对象上的新操作。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"patterns","title":"设计模式","link":"/topics/patterns/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"设计意图与对象责任","scope":"general","audience":"general","group":"原理与设计","summary":"围绕替换计算规则、控制执行流程、组件通信、恢复历史与遍历结构选择模式；区分状态切换、通知机制和对象上的新操作。","status":"active","related":[{"title":"备忘录","link":"/principles/patterns/behavior/memento","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"策略","link":"/principles/patterns/behavior/strategy","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"抽象工厂","link":"/principles/patterns/creation/abstract-factory","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"创建型设计模式","link":"/principles/patterns/creation/patterns-creation-general-general","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"代理","link":"/principles/patterns/structure/proxy","kind":"设计意图与对象责任","scope":"general","audience":"general"}],"prev":{"text":"模板方法","link":"/principles/patterns/behavior/template-method"},"next":{"text":"职责链","link":"/principles/patterns/behavior/chain-of-responsibility"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"模板方法","link":"/principles/patterns/behavior/template-method"},"next":{"text":"职责链","link":"/principles/patterns/behavior/chain-of-responsibility"}},"headers":[],"relativePath":"principles/patterns/behavior/patterns-behavior-general-general.md","filePath":"principles/patterns/behavior/patterns-behavior-general-general.md"}'),i={name:"principles/patterns/behavior/patterns-behavior-general-general.md"};function p(s,e,d,o,l,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="行为型设计模式" tabindex="-1">行为型设计模式 <a class="header-anchor" href="#行为型设计模式" aria-label="Permalink to &quot;行为型设计模式&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>每个 package main 是独立 main.go，需在模块中分别保存；本轮仅静态推导输出，未执行。传入的策略、步骤、监听函数和接口对象必须非 nil；Iterator.Index 要保持在 0..len(Values)，解释器表达式树有限无环。示例均在单个 goroutine 中调用，不能自动视为线程安全。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>替换整段算法，或只替换稳定流程中的步骤</td><td>策略或模板方法</td><td>策略注入计算规则；模板方法固定步骤顺序，Go 可用函数参数与组合表达。</td></tr><tr><td>对象随当前状态改变行为</td><td>状态</td><td>状态类型承载各自行为，转换规则需明确并排除非法转换。</td></tr><tr><td>让请求依次校验，或先保存请求稍后执行</td><td>职责链或命令</td><td>职责链关注顺序和短路；命令封装动作与参数，撤销还需反向操作或旧状态。</td></tr><tr><td>变化时通知多个订阅方，或协调多个组件</td><td>观察者或中介者</td><td>观察者示例同步通知，会被慢回调阻塞；中介者集中协调，需防止职责膨胀。</td></tr><tr><td>保存编辑历史并恢复</td><td>备忘录</td><td>值快照可恢复文本；含切片、映射或外部资源时需明确复制语义和成本。</td></tr><tr><td>隐藏集合存储，或在稳定对象结构上新增操作</td><td>迭代器或访问者</td><td>普通切片可直接 range；访问者增加操作方便，但新增元素类型需修改全部访问者。</td></tr><tr><td>递归求值规则有限的表达式</td><td>解释器</td><td>简单语法树可自行组合；优先级、变量与错误恢复变复杂时应采用正式解析器。</td></tr></tbody></table><h2 id="scene-vary-rules-and-steps" tabindex="-1">替换计算规则、流程步骤与状态行为 <a class="header-anchor" href="#scene-vary-rules-and-steps" aria-label="Permalink to &quot;替换计算规则、流程步骤与状态行为 {#scene-vary-rules-and-steps}&quot;">​</a></h2><h3 id="entry-strategy-721beed283" tabindex="-1">策略 <a class="header-anchor" href="#entry-strategy-721beed283" aria-label="Permalink to &quot;策略 {#entry-strategy-721beed283}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-strategy-721beed283-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/strategy">策略</a>。</p><p>只有一种固定规则时，不必为策略额外设计接口层。</p><h3 id="entry-template-method-74b14019e8" tabindex="-1">模板方法 <a class="header-anchor" href="#entry-template-method-74b14019e8" aria-label="Permalink to &quot;模板方法 {#entry-template-method-74b14019e8}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-template-method-74b14019e8-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/template-method">模板方法</a>。</p><p>流程的固定部分必须稳定，否则频繁增加钩子会让模板难以理解。</p><h3 id="entry-state-d7e414e84e" tabindex="-1">状态 <a class="header-anchor" href="#entry-state-d7e414e84e" aria-label="Permalink to &quot;状态 {#entry-state-d7e414e84e}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-state-d7e414e84e-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/state">状态</a>。</p><p>转换规则需要集中定义，并保证不允许的转换不会悄悄发生。</p><h2 id="scene-route-and-defer-requests" tabindex="-1">顺序处理校验并封装待执行请求 <a class="header-anchor" href="#scene-route-and-defer-requests" aria-label="Permalink to &quot;顺序处理校验并封装待执行请求 {#scene-route-and-defer-requests}&quot;">​</a></h2><h3 id="entry-chain-of-responsibility-61b289aa8b" tabindex="-1">职责链 <a class="header-anchor" href="#entry-chain-of-responsibility-61b289aa8b" aria-label="Permalink to &quot;职责链 {#entry-chain-of-responsibility-61b289aa8b}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-chain-of-responsibility-61b289aa8b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/chain-of-responsibility">职责链</a>。</p><p>若处理器会修改请求，应把执行顺序和错误传播方式定义清楚。</p><h3 id="entry-command-e51719c821" tabindex="-1">命令 <a class="header-anchor" href="#entry-command-e51719c821" aria-label="Permalink to &quot;命令 {#entry-command-e51719c821}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-command-e51719c821-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/command">命令</a>。</p><p>需要撤销时，命令还要保存反向操作或执行前的状态。</p><h2 id="scene-coordinate-components" tabindex="-1">通知订阅者与协调组件通信 <a class="header-anchor" href="#scene-coordinate-components" aria-label="Permalink to &quot;通知订阅者与协调组件通信 {#scene-coordinate-components}&quot;">​</a></h2><h3 id="entry-observer-8a04a89841" tabindex="-1">观察者 <a class="header-anchor" href="#entry-observer-8a04a89841" aria-label="Permalink to &quot;观察者 {#entry-observer-8a04a89841}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-observer-8a04a89841-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/observer">观察者</a>。</p><p>这个同步版本会被慢回调阻塞；生产场景还要考虑退订、异常隔离和并发安全。</p><h3 id="entry-mediator-fcf939e6b4" tabindex="-1">中介者 <a class="header-anchor" href="#entry-mediator-fcf939e6b4" aria-label="Permalink to &quot;中介者 {#entry-mediator-fcf939e6b4}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-mediator-fcf939e6b4-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/mediator">中介者</a>。</p><p>中介者也可能膨胀成过大的协调中心，需要保持职责清晰。</p><h2 id="scene-restore-history" tabindex="-1">保存对象快照并恢复历史状态 <a class="header-anchor" href="#scene-restore-history" aria-label="Permalink to &quot;保存对象快照并恢复历史状态 {#scene-restore-history}&quot;">​</a></h2><h3 id="entry-memento-883284356c" tabindex="-1">备忘录 <a class="header-anchor" href="#entry-memento-883284356c" aria-label="Permalink to &quot;备忘录 {#entry-memento-883284356c}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-memento-883284356c-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/memento">备忘录</a>。</p><p>真实对象含有切片、映射或外部资源时，快照成本与复制语义需要明确。</p><h2 id="scene-visit-and-evaluate" tabindex="-1">遍历集合、扩展对象操作与求值表达式 <a class="header-anchor" href="#scene-visit-and-evaluate" aria-label="Permalink to &quot;遍历集合、扩展对象操作与求值表达式 {#scene-visit-and-evaluate}&quot;">​</a></h2><h3 id="entry-iterator-21fa9922dd" tabindex="-1">迭代器 <a class="header-anchor" href="#entry-iterator-21fa9922dd" aria-label="Permalink to &quot;迭代器 {#entry-iterator-21fa9922dd}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-iterator-21fa9922dd-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/iterator">迭代器</a>。</p><p>对普通切片直接使用 range 更简单；自定义容器或惰性数据源才更需要独立迭代器。</p><h3 id="entry-visitor-ed0d12c78b" tabindex="-1">访问者 <a class="header-anchor" href="#entry-visitor-ed0d12c78b" aria-label="Permalink to &quot;访问者 {#entry-visitor-ed0d12c78b}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-visitor-ed0d12c78b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/visitor">访问者</a>。</p><p>新增元素类型却要求所有访问者增加方法，因此它适合元素种类相对稳定的结构。</p><h3 id="entry-interpreter-1ab49fb60a" tabindex="-1">解释器 <a class="header-anchor" href="#entry-interpreter-1ab49fb60a" aria-label="Permalink to &quot;解释器 {#entry-interpreter-1ab49fb60a}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-interpreter-1ab49fb60a-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/behavior/interpreter">解释器</a>。</p><p>规则一旦出现优先级、变量和错误恢复等需求，就应使用正式解析器。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>观察者第一个回调一直不返回，第二个会收到事件吗？提示：Publish 逐个同步调用。</p><details class="details custom-block"><summary>参考解法</summary><p>不会；后一个回调须等前一个返回。若需要异步隔离，应另定义顺序、容量、错误、退订和退出协议，不能简单加 goroutine 后继续承诺原有通知顺序。</p></details>',67)])])}const m=a(i,[["render",p]]);export{b as __pageData,m as default};
